	MOB_FLAGS[m] = d.boss and MF_BOSS or 0
	if d.fac == FAC_NPC or d.fac == FAC_GUARD then MOB_FLAGS[m] = jbor(MOB_FLAGS[m], MF_INVULN) end
	MOB_PLAYER[m] = -1
	MOB_SPAWNER[m] = -1
